css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; overflow: hidden; border-radius: 14px; }
.loader span { position: absolute; left: 16%; right: 16%; top: 6%; bottom: 18%; border-radius: 12px; background: linear-gradient(150deg, var(--accent), color-mix(in srgb, #000 22%, var(--accent))); box-shadow: 0 6px 14px color-mix(in srgb, #000 22%, transparent); animation: deck-swipe calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; left: 12%; right: 40%; top: 16%; height: 12%; border-radius: 4px; background: color-mix(in srgb, var(--accent-2) 70%, transparent); }
.loader span:nth-of-type(2) { animation-delay: calc(var(--loader-speed) * -2); }
.loader span:nth-of-type(3) { animation-delay: calc(var(--loader-speed) * -1); }
@keyframes deck-swipe { 0% { transform: translate(0, 0) rotate(0deg) scale(1); opacity: 1; } 18% { transform: translate(150%, -12%) rotate(20deg) scale(1); opacity: 0; } 22% { transform: translate(0, 16%) rotate(0deg) scale(.82); opacity: 0; } 40% { transform: translate(0, 16%) rotate(0deg) scale(.82); opacity: .5; } 70% { transform: translate(0, 8%) rotate(0deg) scale(.91); opacity: .8; } 100% { transform: translate(0, 0) rotate(0deg) scale(1); opacity: 1; } }
